const all = $input.all();
const rows = [];
for (const it of all) {
  const j = it.json || {};
  const labelNames = Array.isArray(j.labels) ? j.labels.map(function (l) { return (l && (l.name || l.id)) || ''; }).filter(Boolean).join(', ') : '';
  rows.push({
    from: j.From || j.from || '(unknown sender)',
    subject: j.Subject || j.subject || '(no subject)',
    snippet: String(j.snippet || '').replace(/\s+/g, ' ').slice(0, 220),
    received: j.internalDate || j.date || '',
    labels: labelNames
  });
}
const lines = [];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  lines.push('[' + (i + 1) + '] From: ' + r.from + '\n    Subject: ' + r.subject + '\n    Received: ' + r.received + '\n    Labels: ' + (r.labels || '(none)') + '\n    Snippet: ' + r.snippet);
}
const digestText = rows.length > 0 ? lines.join('\n') : 'No emails were received in the last 24 hours.';
return [{ json: { count: rows.length, emails: rows, digestText: digestText } }];

