const all = $input.all();
const rows = [];
for (const it of all) {
  const j = it.json || {};
  const start = (j.start && (j.start.dateTime || j.start.date)) || '';
  const end = (j.end && (j.end.dateTime || j.end.date)) || '';
  rows.push({
    title: j.summary || '(untitled event)',
    start: start,
    end: end,
    location: j.location || '',
    meetLink: j.hangoutLink || '',
    attendees: Array.isArray(j.attendees) ? j.attendees.length : 0,
    status: j.status || 'confirmed'
  });
}
const lines = [];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  let line = '[' + (i + 1) + '] ' + r.title + '\n    ' + r.start + ' -> ' + r.end + '\n    Attendees: ' + r.attendees;
  if (r.location) { line += '\n    Location: ' + r.location; }
  if (r.meetLink) { line += '\n    Meet link: ' + r.meetLink; }
  lines.push(line);
}
const digestText = rows.length > 0 ? lines.join('\n') : 'No events are scheduled in the selected window.';
return [{ json: { count: rows.length, events: rows, digestText: digestText } }];

