const items = $input.all();
let emailAnalysis = null;
let calendarAnalysis = null;
for (const it of items) {
  const raw = (it.json || {}).output;
  let obj = raw;
  if (typeof raw === 'string') { try { obj = JSON.parse(raw); } catch (e) { obj = null; } }
  if (!obj) { continue; }
  if (obj.section === 'email' && !emailAnalysis) { emailAnalysis = obj; }
  if (obj.section === 'calendar' && !calendarAnalysis) { calendarAnalysis = obj; }
}
if (!emailAnalysis) { emailAnalysis = { section: 'email', totalAnalyzed: 0, priorityInbox: [], reading: [], noise: [], keyThemes: 'Email analysis unavailable in this run.' }; }
if (!calendarAnalysis) { calendarAnalysis = { section: 'calendar', totalEvents: 0, overview: 'Calendar analysis unavailable in this run.', meetings: [], focusWindows: '', conflicts: [], busiestPeriod: '' }; }
const now = new Date().toISOString();
return [{ json: { generatedAt: now, briefingDate: now.slice(0, 10), emailAnalysis: emailAnalysis, calendarAnalysis: calendarAnalysis } }];

