const raw = $input.first().json || {};
let b = raw.output !== undefined ? raw.output : raw;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const esc = function (v) { return String(v === undefined || v === null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const arr = function (v) { return Array.isArray(v) ? v : []; };
const priorities = arr(b.topPriorities);
const emails = arr(b.emailHighlights);
const meetings = arr(b.meetingHighlights);
const actions = arr(b.actionItems);
const COLOR = { high: '#e5484d', medium: '#f0a020', low: '#30a46c' };
const dot = function (p) { const c = COLOR[String(p || '').toLowerCase()] || '#8e8ea0'; return '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:' + c + ';margin-right:8px;"></span>'; };
const prioBar = function (p) { const c = COLOR[String(p || '').toLowerCase()] || '#8e8ea0'; return '<span style="display:inline-block;padding:2px 10px;border-radius:999px;font-size:11px;font-weight:600;color:#ffffff;background:' + c + ';">' + esc(String(p || 'normal').toUpperCase()) + '</span>'; };
const genAt = new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC';

let priosHtml = '';
for (const p of priorities) {
  priosHtml += '<tr><td style="padding:8px 0;border-bottom:1px solid #ececf1;">' + dot(p.source) + '<span style="font-size:14px;color:#1a1a2e;font-weight:600;">' + esc(p.title) + '</span>' + (p.reason ? '<br><span style="font-size:12px;color:#6b6b80;padding-left:18px;">' + esc(p.reason) + '</span>' : '') + '</td></tr>';
}
if (!priosHtml) { priosHtml = '<tr><td style="padding:8px 0;color:#6b6b80;font-size:13px;">No priorities flagged today.</td></tr>'; }

let emailsHtml = '';
for (const m of emails) {
  emailsHtml += '<tr><td style="padding:10px 12px;border-bottom:1px solid #ececf1;">' + prioBar(m.priority) + ' <span style="font-size:13px;color:#1a1a2e;font-weight:600;">' + esc(m.subject) + '</span><br><span style="font-size:12px;color:#6b6b80;">From ' + esc(m.from) + '</span>' + (m.summary ? '<br><span style="font-size:12px;color:#3d3d56;">' + esc(m.summary) + '</span>' : '') + '</td></tr>';
}
if (!emailsHtml) { emailsHtml = '<tr><td style="padding:10px 12px;color:#6b6b80;font-size:13px;">No email highlights for today.</td></tr>'; }

let meetsHtml = '';
for (const g of meetings) {
  const st = String(g.start || '');
  const en = String(g.end || '');
  const stLabel = st.length >= 16 ? st.slice(11, 16) : st;
  const dayLabel = st.length >= 10 ? st.slice(0, 10) : '';
  meetsHtml += '<tr><td style="padding:10px 12px;border-bottom:1px solid #ececf1;white-space:nowrap;font-size:13px;color:#4f46e5;font-weight:700;vertical-align:top;width:70px;">' + esc(dayLabel) + '<br>' + esc(stLabel) + '</td><td style="padding:10px 12px;border-bottom:1px solid #ececf1;font-size:13px;color:#1a1a2e;font-weight:600;vertical-align:top;">' + esc(g.title) + (g.note ? '<br><span style="font-size:12px;color:#6b6b80;font-weight:400;">' + esc(g.note) + '</span>' : '') + '</td><td style="padding:10px 12px;border-bottom:1px solid #ececf1;vertical-align:top;">' + prioBar(g.priority) + '</td></tr>';
}
if (!meetsHtml) { meetsHtml = '<tr><td style="padding:10px 12px;color:#6b6b80;font-size:13px;">No meetings scheduled.</td></tr>'; }

let actsHtml = '';
for (const a of actions) {
  const tag = a.source ? ' <span style="font-size:10px;color:#8e8ea0;">[' + esc(a.source) + ']</span>' : '';
  actsHtml += '<tr><td style="padding:7px 0;border-bottom:1px solid #ececf1;font-size:13px;color:#1a1a2e;">' + dot('#4f46e5') + esc(a.action) + tag + '</td></tr>';
}
if (!actsHtml) { actsHtml = '<tr><td style="padding:7px 0;color:#6b6b80;font-size:13px;">Nothing to act on right now.</td></tr>'; }

const kpi = function (num, label, bg) { return '<td style="background:' + bg + ';border-radius:10px;padding:14px 10px;text-align:center;width:25%;"><div style="font-size:22px;font-weight:800;color:#ffffff;">' + num + '</div><div style="font-size:11px;color:rgba(255,255,255,0.85);text-transform:uppercase;letter-spacing:0.5px;">' + label + '</div></td>'; };

const html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Daily Briefing</title></head>' +
'<body style="margin:0;padding:0;background:#f4f4f8;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;">' +
'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f8;padding:24px 0;"><tr><td align="center">' +
'<table role="presentation" width="720" cellpadding="0" cellspacing="0" style="max-width:720px;width:96%;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 2px 8px rgba(20,20,43,0.08);">' +
'<tr><td style="background:#141433;background-image:linear-gradient(135deg,#141433 0%,#4338ca 100%);padding:28px 32px;">' +
'<div style="font-size:12px;color:#a5b4fc;text-transform:uppercase;letter-spacing:2px;font-weight:700;">Daily Briefing</div>' +
'<div style="font-size:24px;font-weight:800;color:#ffffff;margin-top:6px;">' + esc(b.headline || 'Your day at a glance') + '</div>' +
(b.daySummary ? '<div style="font-size:14px;color:#c7d2fe;margin-top:10px;line-height:1.5;">' + esc(b.daySummary) + '</div>' : '') +
'</td></tr>' +
'<tr><td style="padding:20px 32px 4px 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="8"><tr>' +
kpi(priorities.length, 'Priorities', '#4f46e5') + kpi(emails.length, 'Email highlights', '#e5484d') + kpi(meetings.length, 'Meetings', '#0ea5e9') + kpi(actions.length, 'Action items', '#30a46c') +
'</tr></table></td></tr>' +
'<tr><td style="padding:12px 32px;"><div style="font-size:13px;font-weight:800;color:#141433;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Top priorities</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + priosHtml + '</table></td></tr>' +
'<tr><td style="padding:12px 32px;"><div style="font-size:13px;font-weight:800;color:#141433;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Meetings & events</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #ececf1;border-radius:10px;">' + meetsHtml + '</table></td></tr>' +
'<tr><td style="padding:12px 32px;"><div style="font-size:13px;font-weight:800;color:#141433;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Emails worth attention</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #ececf1;border-radius:10px;">' + emailsHtml + '</table></td></tr>' +
'<tr><td style="padding:12px 32px;"><div style="font-size:13px;font-weight:800;color:#141433;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Action items</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + actsHtml + '</table></td></tr>' +
'<tr><td style="padding:16px 32px 24px 32px;border-top:1px solid #ececf1;"><div style="font-size:11px;color:#9ca3af;">Compiled by the bench-81edc43c multi-agent pipeline (Email Analyst, Calendar Analyst, Briefing Director) - generated ' + esc(genAt) + '.</div></td></tr>' +
'</table></td></tr></table></body></html>';

return [{ json: { subject: 'Daily Briefing - ' + esc(b.headline || 'Your day at a glance'), html: html, priorityCount: priorities.length, emailCount: emails.length, meetingCount: meetings.length, actionCount: actions.length } }];
